}

const tasks = [
  { id: 1, title: 'Read book', done: true },
  { id: 2, title: 'Write code', done: false },
];

function PendingTasks() {
  const pending = tasks.filter(task => !task.done);
  return (
    <ul>
      {pending.map(task => <li key={task.id}>{task.title}</li>)}
    </ul>
  );
}

